style.css:
/* Google 2015 Black Bar Theme */

body::before {
    content: "";
    position: fixed;
    top: 0;
    left: 0;
    width: 100%;
    height: 29px;
    background: #2d2d2d;
    border-bottom: 1px solid #000;
    z-index: 9999;
}

/* Fake old nav links */
body::after {
    content: "Web   Images   Maps   Play   YouTube   News   Gmail   Drive   Calendar   More";
    position: fixed;
    top: 7px;
    left: 15px;
    color: #ccc;
    font-family: Arial, sans-serif;
    font-size: 13px;
    z-index: 10000;
    white-space: pre;
    pointer-events: none;
}

/* Push content down */
body {
    margin-top: 29px !important;
    font-family: Arial !important;
}

/* Old search box feel */
textarea,
input[name="q"] {
    border: 1px solid #d9d9d9 !important;
    border-radius: 1px !important;
    box-shadow: none !important;
}

/* Old buttons */
input[type="submit"],
button {
    border-radius: 2px !important;
    background: #f5f5f5 !important;
    border: 1px solid #dcdcdc !important;
    font-family: Arial !important;
    font-size: 11px !important;
}

/* Remove modern rounded stuff */
* {
    border-radius: 0 !important;
}
